// ❌ false sharing: 8개가 한 라인(64B)에 몰림
struct Bad { int counter[8]; };

// ✅ 패딩: 각 카운터를 64바이트 라인에 독점
struct alignas(64) PaddedCounter {
    int value;
    char pad[64 - sizeof(int)]; // 라인 채워 이웃과 분리
};
PaddedCounter counters[8]; // 이제 서로 다른 라인 → 간섭 0

// 큰 데이터: 패딩(64MB) 대신 스레드로컬 + 합산
void worker(int id) {
    long local = 0;                 // 각 스레드 자기 것 (공유 아님 → false sharing 0)
    for (auto& x : chunk[id]) local += f(x);
    results[id] = local;            // 끝에 딱 한 번만 공유에 씀
}
// 마지막에 results 를 합산 → 공유 쓰기가 루프당 0회
